#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {  // Child process
        printf("Child process\n");
        exit(0);
    } else if (pid > 0) {  // Parent process
        wait(NULL);  // Wait for child to terminate
        printf("Child has terminated\n");
    } else {
        perror("fork failed");
    }
    return 0;
}
